import React, { useEffect, useState } from "react";
import { FiPlus, FiMinus } from "react-icons/fi";
import { useNavigate } from "react-router-dom";
import { useShopCart } from "../ShopCartContext";
import "../CSS/ECommerce.css";
import axios from "axios";
import staticProducts from "../../data/products.json";

const PetCare = () => {
  const [products, setProducts] = useState([]);
  const [dbSubcategories, setDbSubcategories] = useState([]);
  const [loading, setLoading] = useState(true);

  const navigate = useNavigate();
  const { shopCartItems, addToShopCart, updateShopQuantity } = useShopCart();
  const baseURL = process.env.REACT_APP_BACKEND_URL || "http://localhost:5002";

  useEffect(() => {
    fetchPetCareData();
  }, []);

  const fetchPetCareData = async () => {
    try {
      setLoading(true);

      // 1. Fetch admin configuration for petCare
      const configRes = await axios.get(`${baseURL}/api/shop-featured-config/petCare`);
      if (configRes.data?.success && configRes.data?.data) {
        const configData = configRes.data.data;

        // Set featured products if configured
        if (Array.isArray(configData.featuredProducts) && configData.featuredProducts.length > 0) {
          setProducts(configData.featuredProducts);
        } else {
          await fetchFallbackProducts();
        }

        // Set subcategories if configured
        if (Array.isArray(configData.featuredSubcategories)) {
          const validSubcats = configData.featuredSubcategories.filter(
            (item) => item.subCategoryName && item.subCategoryName.trim() !== ""
          );
          setDbSubcategories(validSubcats);
        }
      } else {
        await fetchFallbackProducts();
      }
    } catch (error) {
      console.error("Error loading Pet Care configuration:", error);
      await fetchFallbackProducts();
    } finally {
      setLoading(false);
    }
  };

  const fetchFallbackProducts = async () => {
    try {
      const res = await axios.get(`${baseURL}/api/products`, {
        params: {
          category: "Pet Care",
          page: 1,
          limit: 6,
        },
      });
      if (res.data?.products && Array.isArray(res.data.products)) {
        setProducts(res.data.products);
      }
    } catch (err) {
      console.error("Error fetching fallback pet care products:", err);
    }
  };

  const getProductName = (item) => item?.productName || item?.name || "Pet Care Product";
  const getProductImg = (item) => {
    if (item?.img) return item.img;
    if (Array.isArray(item?.imageUrls) && item.imageUrls.length > 0) return item.imageUrls[0];
    return "/assets/images/Shop/not_available.jpg";
  };
  const getProductMarketer = (item) => item?.marketer || item?.marketingCompany || item?.subCategory || "";
  const getProductPrice = (item) => item?.price || item?.mrp || 0;

  const handleAddToCart = (item) => {
    addToShopCart({
      _id: item._id || item.id,
      name: getProductName(item),
      price: getProductPrice(item),
      mrp: item.mrp || getProductPrice(item),
      category: item.category || "Pet Care",
      subCategory: item.subCategory || "",
      marketer: getProductMarketer(item),
      img: getProductImg(item),
      prescription_required: item.prescriptionRequired === "true" ? "Yes" : "No",
      quantity: 1,
      composition: item?.composition,
      package_details: item?.packaging || item?.packaging_detail,
    });
  };

  const fallbackSubcategories = staticProducts.filter(
    (item) => item.category === "Pet Care"
  );

  const displaySubcategories =
    dbSubcategories.length > 0
      ? dbSubcategories.map((item, idx) => ({
          id: idx,
          subCategory: item.subCategoryName,
          img: item.imageUrl.startsWith("http")
            ? item.imageUrl
            : `${baseURL}${item.imageUrl}`,
        }))
      : fallbackSubcategories;

  return (
    <div style={{ backgroundColor: "#fff", paddingBottom: "30px" }}>
      {/* 1. Featured Pet Care Products Section */}
      <section className="pet-care-products pt-4 pt-md-5 pb-4 pb-md-5" style={{ backgroundColor: "#fff" }}>
        <div className="container-fluid" style={{ padding: "0 4%" }}>
          <div className="d-flex justify-content-between align-items-center gap-2 mb-3 mb-md-4">
            <div>
              <h3 style={{ fontWeight: "800", color: "#1A202C", margin: 0, fontSize: "24px" }}>
                Pet Care Products
              </h3>
              <p style={{ color: "#718096", fontSize: "14px", margin: "4px 0 0 0" }}>
                Essential food, grooming and health supplies for your pets
              </p>
            </div>
            <button
              onClick={() => navigate("/all-products?category=Pet%20Care")}
              style={{
                color: "#A847F0",
                background: "none",
                border: "none",
                fontWeight: "700",
                fontSize: "14px",
                whiteSpace: "nowrap",
                flexShrink: 0,
              }}
            >
              View All
            </button>
          </div>

          {loading ? (
            <div className="text-center py-4">
              <div className="spinner-border text-primary" role="status" style={{ color: "#A847F0" }}>
                <span className="visually-hidden">Loading pet care products...</span>
              </div>
            </div>
          ) : (
            <div className="row g-2 g-md-3">
              {products.map((item, idx) => {
                const itemId = item._id || item.id;
                const cartItem = shopCartItems.find((cart) => cart._id === itemId);
                const isAdded = !!cartItem;
                const currentQty = cartItem?.quantity || 1;

                return (
                  <div className="col-xl-2 col-lg-3 col-md-4 col-6" key={itemId || idx}>
                    <div
                      className="medicine-card"
                      style={{
                        backgroundColor: "#fff",
                        borderRadius: "8px",
                        padding: "10px",
                        border: "1px solid #E2E8F0",
                        boxShadow: "0 2px 8px rgba(0, 0, 0, 0.04)",
                        height: "100%",
                        display: "flex",
                        flexDirection: "column",
                        transition: "all 0.3s ease",
                        overflow: "hidden",
                        position: "relative",
                      }}
                    >
                      <div
                        style={{
                          height: "140px",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          margin: "-10px -10px 10px -10px",
                          position: "relative",
                          backgroundColor: "#f8fafc",
                          borderBottom: "1px solid #F1F5F9",
                          cursor: "pointer",
                        }}
                        onClick={() => navigate(`/${item.category || "pet-care"}/${itemId}`)}
                      >
                        <img
                          src={getProductImg(item)}
                          alt={getProductName(item)}
                          style={{
                            height: "100%",
                            width: "100%",
                            objectFit: "contain",
                          }}
                          onError={(e) => {
                            e.target.src = "/assets/images/Shop/not_available.jpg";
                          }}
                        />
                      </div>

                      <div style={{ flexGrow: 1 }}>
                        <h6
                          style={{
                            fontSize: "14px",
                            fontWeight: "700",
                            color: "#1A202C",
                            lineHeight: "1.3",
                            height: "36px",
                            overflow: "hidden",
                            display: "-webkit-box",
                            WebkitLineClamp: 2,
                            WebkitBoxOrient: "vertical",
                            marginBottom: "6px",
                            cursor: "pointer",
                          }}
                          onClick={() => navigate(`/${item.category || "pet-care"}/${itemId}`)}
                        >
                          {getProductName(item)}
                        </h6>
                        <p
                          style={{
                            fontSize: "12px",
                            color: "#718096",
                            marginBottom: "8px",
                            fontWeight: "500",
                            whiteSpace: "nowrap",
                            overflow: "hidden",
                            textOverflow: "ellipsis",
                            height: "16px",
                          }}
                        >
                          {getProductMarketer(item)}
                        </p>
                      </div>

                      <div
                        className="d-flex align-items-center justify-content-between pt-2"
                        style={{ borderTop: "1px solid #F1F5F9" }}
                      >
                        <div>
                          <h6
                            style={{
                              margin: 0,
                              fontWeight: "800",
                              color: "#A847F0",
                              fontSize: "16px",
                            }}
                          >
                            ₹{getProductPrice(item)}
                          </h6>
                        </div>
                        {!isAdded ? (
                          <button
                            onClick={() => handleAddToCart(item)}
                            className="shop-add-btn"
                          >
                            <FiPlus size={16} /> Add
                          </button>
                        ) : (
                          <div className="shop-qty-control">
                            <button
                              type="button"
                              onClick={() => updateShopQuantity(itemId, currentQty - 1)}
                              className="shop-qty-value"
                            >
                              <FiMinus size={16} />
                            </button>

                            <span
                              style={{
                                fontWeight: "700",
                                color: "#1E293B",
                                fontSize: "14px",
                              }}
                            >
                              {currentQty}
                            </span>

                            <button
                              type="button"
                              onClick={() => updateShopQuantity(itemId, currentQty + 1)}
                              className="shop-qty-btn"
                            >
                              <FiPlus size={16} />
                            </button>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </section>

      {/* 2. Pet Care Sub-Categories Section */}
      {displaySubcategories.length > 0 && (
        <section className="pet-care-sub-categories pt-2 pb-5" style={{ backgroundColor: "#fff" }}>
          <div className="container-fluid" style={{ padding: "0 4%" }}>
            <div className="d-flex justify-content-between align-items-center gap-2 mb-3 mb-md-4">
              <div>
                <h3 style={{ fontWeight: "800", color: "#1A202C", margin: 0, fontSize: "24px" }}>
                  Pet Care Sub-Categories
                </h3>
                <p style={{ color: "#718096", fontSize: "14px", margin: "4px 0 0 0" }}>
                  Discover food, treats, toys, and grooming for your beloved pets
                </p>
              </div>
              <button
                onClick={() => navigate("/all-products?category=Pet%20Care")}
                style={{
                  color: "#A847F0",
                  background: "none",
                  border: "none",
                  fontWeight: "700",
                  fontSize: "14px",
                  whiteSpace: "nowrap",
                  flexShrink: 0,
                }}
              >
                View All
              </button>
            </div>

            <div className="row g-2 g-md-3">
              {displaySubcategories.map((cat, idx) => (
                <div className="col-xl-2 col-lg-3 col-md-4 col-6" key={cat.id || idx}>
                  <div
                    className="subcategory-card"
                    onClick={() =>
                      navigate(
                        `/all-products?category=Pet%20Care&subCategory=${encodeURIComponent(
                          cat.subCategory
                        )}`
                      )
                    }
                    style={{
                      cursor: "pointer",
                      transition: "all 0.3s ease",
                    }}
                  >
                    <div
                      style={{
                        borderRadius: "8px",
                        overflow: "hidden",
                        border: "1px solid #E2E8F0",
                        backgroundColor: "#fdf2f8",
                        transition: "all 0.35s ease-in-out",
                      }}
                      className="pet-sub-card-image"
                    >
                      <img
                        src={cat.img}
                        alt={cat.subCategory}
                        style={{
                          width: "100%",
                          height: "100%",
                          objectFit: "contain",
                        }}
                        onError={(e) => {
                          e.target.src = "/assets/images/Shop/not_available.jpg";
                        }}
                      />
                    </div>

                    <h6 className="pet-subcat-title">
                      {cat.subCategory}
                    </h6>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      <style>{`
        .pet-sub-card-image {
          height: 180px;
        }
        .pet-subcat-title {
          margin-top: 10px;
          text-align: center;
          font-size: 14px;
          font-weight: 700;
          color: #1A202C;
        }
        .pet-sub-card-image:hover {
          transform: translateY(-4px);
          box-shadow: 0 10px 20px rgba(124, 58, 237, 0.12);
          border-color: #A847F0 !important;
        }
        @media (max-width: 767px) {
          .pet-sub-card-image {
            height: 110px !important;
            border-radius: 8px !important;
          }
          .pet-subcat-title {
            margin-top: 6px !important;
            font-size: 12.5px !important;
          }
        }
        @media (max-width: 420px) {
          .pet-sub-card-image {
            height: 98px !important;
          }
          .pet-subcat-title {
            font-size: 11.5px !important;
          }
        }
      `}</style>
    </div>
  );
};

export default PetCare;
