import React from 'react';
import { Link } from 'react-router-dom';
import { Swiper, SwiperSlide } from 'swiper/react';
import { Navigation, Pagination, Autoplay } from 'swiper';


// Import Swiper styles
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';

const CategoryBanner = () => {
  const banners = [
    {
      id: 1,
      title: "Medicines & Cosmetics",
      desc: "Get authentic medicines delivered directly to your doorstep.",
      bg: "#F0F7FF", // Light Blue
      // accent: "#3B82F6",
      accent: "#DB2777",
      img: "/assets/images/banner/4.jpg",
      link: "/all-products?category=Medicines",
      btnText: "View All"
    },
    {
      id: 2,
      title: "Medical devices & surgical equipment ",
      desc: "Advanced healthcare tools for professional and home use.",
      bg: "#FFF7ED", // Light Orange
      accent: "#F97316",
      img: "/assets/images/banner/1.jpg",
      link: "/all-products?category=Medical%20devices%20%26%20surgical%20equipment",
      btnText: "View All"
    },
    // {
    //   id: 3,
    //   title: "Skin & hair care",
    //   desc: "Dermatologically tested skincare and beauty essentials.",
    //   bg: "#FDF2F8", // Light Pink
    //   accent: "#3B82F6",
    //   img: "/assets/images/banner/2.jpg",
    //   link: "/all-products?category=Skin%20%26%20Hair%20Care",
    //   btnText: "View All"
    // },
   {
  id: 3,
  title: "Health Supplements",
  desc: "Boost your wellness with essential vitamins, minerals, and daily nutrition support.",
  bg: "#F8FAFC",
  accent: "#475569",
  img: "/assets/images/banner/8.jpg",
  link: "/all-products?category=Health%20Supplements",
  btnText: "View All"
},
{
  id: 4,
  title: "Pet Care",
  desc: "Quality healthcare products and medicines to support your pets’ health and well-being.",
  bg: "#F8FAFC",
  accent: "#3B82F6",
  img: "/assets/images/banner/7.jpg",
  link: "/all-products?category=Pet%20Care",
  btnText: "View All"
}
  ];

  return (    <section className="promo-banners-slider">
      <style>{`
        .promo-banners-slider {
          padding-top: 8px !important;
          padding-bottom: 6px !important;
        }
        .promo-swiper {
          padding-bottom: 22px !important;
          position: relative;
        }
        .promo-swiper .swiper-pagination {
          bottom: 0px !important;
          display: flex;
          justify-content: center;
          align-items: center;
          gap: 6px;
          z-index: 10;
        }
        .promo-swiper .swiper-pagination-bullet {
          background: #cbd5e1;
          opacity: 1;
          width: 8px;
          height: 8px;
          margin: 0 !important;
          transition: all 0.3s ease;
        }
        .promo-swiper .swiper-pagination-bullet-active {
          background: #A847F0 !important;
          width: 25px;
          height: 8px;
          border-radius: 5px;
        }
        .promo-card {
          transition: all 0.3s ease-in-out;
          border-radius: 12px !important;
        }
        .promo-card:hover {
          transform: translateY(-2px);
          box-shadow: 0 12px 24px rgba(0,0,0,0.05);
          border-color: #e2e8f0 !important;
        }
        @media (max-width: 991px) {
          .promo-banners-slider {
            padding-top: 4px !important;
            padding-bottom: 4px !important;
          }
          .promo-swiper {
            padding-bottom: 20px !important;
          }
          .promo-swiper .swiper-pagination {
            bottom: 0px !important;
          }
        }
        @media (max-width: 576px) {
          .promo-banners-slider {
            padding-top: 2px !important;
            padding-bottom: 2px !important;
          }
          .promo-swiper {
            padding-bottom: 18px !important;
          }
          .promo-swiper .swiper-pagination {
            bottom: 0px !important;
          }
          .promo-card {
            border-radius: 10px !important;
            min-height: 180px !important;
          }
          .promo-card-content {
            padding: 18px 16px !important;
            max-width: 65% !important;
          }
          .promo-card-title {
            font-size: 17px !important;
            margin-bottom: 6px !important;
          }
          .promo-card-desc {
            font-size: 12px !important;
            margin-bottom: 12px !important;
            line-height: 1.4 !important;
          }
        }
      `}</style>
      <div className="container-fluid" style={{ padding: '0 4%' }}>
        <Swiper
          modules={[Navigation, Pagination, Autoplay]}
          spaceBetween={16}
          slidesPerView={1}
          centeredSlides={false} // Ensures cards are full width/aligned left
          pagination={{ clickable: true }}
          autoplay={{ delay: 5000, disableOnInteraction: false }}
          breakpoints={{
            768: { slidesPerView: 2, spaceBetween: 20 },
            1200: { slidesPerView: 3, spaceBetween: 24 } // 3 full cards on desktop
          }}
          className="promo-swiper"
        >
          {banners.map((banner) => (
            <SwiperSlide key={banner.id}>
              <div
                className="promo-card h-100 position-relative overflow-hidden"
                style={{
                  borderRadius: "12px",
                  minHeight: "200px",
                  display: "flex",
                  border: `1px solid ${banner.bg}`,
                  background: banner.bg,
                }}
              >
                {/* Background Image */}
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    backgroundImage: `url(${banner.img})`,
                    backgroundSize: "cover",
                    backgroundPosition: "center",
                    backgroundRepeat: "no-repeat",
                    opacity: 0.8, // Adjust visibility
                    zIndex: 0,
                  }}
                />

                {/* Optional Overlay */}
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    zIndex: 1,
                  }}
                />

                {/* Content */}
                <div
                  className="promo-card-content"
                  style={{
                    position: "relative",
                    zIndex: 2,
                    padding: "28px 26px",
                    maxWidth: "62%",
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                  }}
                >
                  <h4
                    className="promo-card-title"
                    style={{
                      fontWeight: "800",
                      marginBottom: "10px",
                      fontSize: "20px",
                      color: "#1E293B",
                      lineHeight: "1.3"
                    }}
                  >
                    {banner.title}
                  </h4>

                  <p
                    className="promo-card-desc"
                    style={{
                      fontSize: "13.5px",
                      color: "#475569",
                      marginBottom: "18px",
                      lineHeight: "1.55",
                    }}
                  >
                    {banner.desc}
                  </p>

                  <Link
                    to={banner.link}
                    style={{
                      backgroundColor: banner.accent,
                      color: "#fff",
                      padding: "9px 20px",
                      borderRadius: "10px",
                      fontSize: "13px",
                      fontWeight: "700",
                      textDecoration: "none",
                      width: "fit-content",
                    }}
                  >
                    {banner.btnText}
                  </Link>
                </div>
              </div>
            </SwiperSlide>
          ))}
        </Swiper>
      </div>
    </section>
  );
};

export default CategoryBanner;