import React from 'react';
import { useNavigate } from 'react-router-dom';

const BrowseHealthCondition = () => {
  const navigate = useNavigate();

  const conditions = [
    {
      name: "Diabetes",
      image: "/assets/images/Shop/2.png",
      bg: "#E1F5FE",
      category: "Medicines",
      subCategory: "Diabetes"
    },
    {
      name: "Hair Care",
      image: "/assets/images/Shop/Skin1.png",
      bg: "#F3E5F5",
      category: "Medicines",
      subCategory: "Hair Care"
    },
    {
      name: "First Aid & Wound Care",
      image: "/assets/images/Shop/FirstAid.png",
      bg: "#ffd7d7",
      category: "Medical devices & surgical equipment",
      subCategory: "First Aid"
    },
    {
      name: "Nutritional Drinks",
      image: "/assets/images/Shop/NutritionalDrink.png",
      bg: "#E1F5FE",
      category: "Health Supplements",
      subCategory: "Nutritional Drinks"
    },
    {
      name: "Women's Health",
      image: "/assets/images/Shop/womenhealth.png",
      bg: "#FCE4EC",
      category: "Medicines",
      subCategory: "Feminine Care"
    },
    {
      name: "Fever & Infection",
      image: "/assets/images/Shop/4.png",
      bg: "#E8EAF6",
      category: "Medicines",
      subCategory: "Fever & Headache"
    },
    {
      name: "Baby Care",
      image: "/assets/images/Shop/BabyCare.png",
      bg: "#EEC8F4",
      category: "Medicines",
      subCategory: "Baby Care"
    }
  ];

  const handleConditionClick = (item) => {
    navigate(
      `/all-products?category=${encodeURIComponent(item.category)}&subCategory=${encodeURIComponent(item.subCategory)}`
    );
  };

  return (
    <section className="browse-health-section">
      <style>
        {`
          @media (min-width: 1200px) {
            .col-xl-custom-7 {
              flex: 0 0 auto;
              width: 14.285%;
            }
          }

          .browse-health-section {
            padding-bottom: 20px;
          }

          .health-condition-card {
            border-radius: 8px;
            height: 130px;
            position: relative;
            overflow: hidden;
            cursor: pointer;
            transition: all 0.3s ease;
            border: 1px solid transparent;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 8px;
          }

          .health-condition-card:hover {
            transform: translateY(-3px);
            box-shadow: 0 8px 16px rgba(124, 58, 237, 0.08);
            border-color: #A847F0 !important;
          }

          .health-condition-title {
            font-weight: 600;
            font-size: 14px;
            color: #475569;
            line-height: 1.25;
            margin: 0;
          }

          .health-condition-heading {
            font-weight: 800;
            color: #1A202C;
            font-size: 22px;
          }

          @media (max-width: 991px) {
            .browse-health-section {
              padding-bottom: 16px;
            }
            .health-condition-card {
              height: 115px;
              margin-bottom: 6px;
            }
            .health-condition-title {
              font-size: 13px;
            }
          }

          @media (max-width: 767px) {
            .browse-health-section {
              padding-bottom: 12px;
            }
            .health-condition-heading {
              font-size: 17px;
              margin-bottom: 10px !important;
            }
            .health-condition-card {
              height: 80px;
              border-radius: 8px;
              margin-bottom: 3px;
            }
            .health-condition-title {
              font-size: 11px;
              line-height: 1.2;
            }
          }

          @media (max-width: 380px) {
            .health-condition-card {
              height: 74px;
              border-radius: 6px;
              margin-bottom: 2px;
            }
            .health-condition-title {
              font-size: 10px;
              line-height: 1.15;
            }
          }
        `}
      </style>

      <div className="container-fluid" style={{ padding: '0 4%' }}>
        <div className="section-heading text-center mb-2 mb-md-3">
          <h3 className="health-condition-heading">
            Browse by Health Conditions
          </h3>
        </div>

        <div className="row g-2 g-md-3 justify-content-center">
          {conditions.map((item, index) => (
            <div
              className="col-xl-custom-7 col-lg-3 col-md-4 col-4"
              key={index}
            >
              <div
                className="health-condition-card"
                onClick={() => handleConditionClick(item)}
                style={{
                  backgroundColor: item.bg,
                }}
              >
                <div
                  style={{
                    width: '100%',
                    height: '100%',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    padding: '6px'
                  }}
                >
                  <img
                    src={item.image}
                    alt={item.name}
                    style={{
                      maxWidth: '85%',
                      maxHeight: '85%',
                      objectFit: 'contain',
                      transition: 'transform 0.3s ease'
                    }}
                    className="card-image"
                  />
                </div>

                <div
                  style={{
                    position: 'absolute',
                    top: '-15%',
                    right: '-15%',
                    width: '55px',
                    height: '55px',
                    background: 'rgba(255,255,255,0.25)',
                    borderRadius: '50%',
                    zIndex: 1
                  }}
                />
              </div>

              <div style={{ textAlign: 'center', padding: '0 2px' }}>
                <h6 className="health-condition-title">
                  {item.name}
                </h6>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default BrowseHealthCondition;