import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import staticProducts from "../../data/products.json";

const BeautySubCategory = () => {
  const navigate = useNavigate();
  const [dbSubcategories, setDbSubcategories] = useState([]);
  const baseURL = process.env.REACT_APP_BACKEND_URL || "http://localhost:5002";

  useEffect(() => {
    fetch(`${baseURL}/api/shop-featured-config/healthSupplements`)
      .then((res) => res.json())
      .then((data) => {
        if (data.success && data.data && Array.isArray(data.data.featuredSubcategories)) {
          const validSubcats = data.data.featuredSubcategories.filter(
            (item) => item.subCategoryName && item.subCategoryName.trim() !== ""
          );
          if (validSubcats.length > 0) {
            setDbSubcategories(validSubcats);
          }
        }
      })
      .catch((err) => console.error("Error loading Health Supplements subcategories:", err));
  }, [baseURL]);

  const fallbackCategories = staticProducts.filter(
    (item) => item.category === "Health Supplements" || item.category === "Beauty Products"
  );

  const displayItems =
    dbSubcategories.length > 0
      ? dbSubcategories.map((item, idx) => ({
          id: idx,
          subCategory: item.subCategoryName,
          img: item.imageUrl.startsWith("http")
            ? item.imageUrl
            : `${baseURL}${item.imageUrl}`,
        }))
      : fallbackCategories;

  return (
    <section className="beauty-sub-category pt-4 pt-md-5 pb-4 pb-md-5" style={{ backgroundColor: "#fff" }}>
      <div className="container-fluid" style={{ padding: "0 4%" }}>
        {/* Section Header */}
        <div className="d-flex justify-content-between align-items-center gap-2 mb-3 mb-md-4">
          <div>
            <h3 style={{ fontWeight: "800", color: "#1A202C", margin: 0, fontSize: "24px" }}>
            Explore Wellness Essentials
            </h3>
            <p style={{ color: "#718096", fontSize: "14px", margin: "4px 0 0 0" }}>
            Discover vitamins, supplements and nutrition products for your daily needs.
            </p>
          </div>
          <button
            onClick={() => navigate("/all-products?category=Health%20Supplements")}
            style={{
              color: "#A847F0",
              background: "none",
              border: "none",
              fontWeight: "700",
              fontSize: "14px",
              whiteSpace: "nowrap",
              flexShrink: 0,
            }}
          >
            View All
          </button>
        </div>

        {/* Product Grid - 6 columns */}
        <div className="row g-2 g-md-3">
          {displayItems.map((item, idx) => (
            <div className="col-xl-2 col-lg-3 col-md-4 col-6" key={item.id || idx}>
              <div
                className="beauty-sub-card"
                onClick={() =>
                  navigate(
                    `/all-products?category=Health%20Supplements&subCategory=${encodeURIComponent(
                      item.subCategory
                    )}`
                  )
                }
                style={{
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                }}
              >
                {/* Image Banner Container */}
                <div
                  style={{
                    borderRadius: "8px",
                    overflow: "hidden",
                    border: "1px solid #E2E8F0",
                    backgroundColor: "#fdf2f8",
                    boxShadow: "0 2px 8px rgba(0,0,0,0.04)",
                    transition: "all 0.35s ease-in-out",
                  }}
                  className="beauty-sub-card-image"
                >
                  <img
                    src={item.img}
                    alt={item.subCategory}
                    style={{
                      width: "100%",
                      height: "100%",
                      objectFit: "contain",
                    }}
                    onError={(e) => {
                      e.target.src = "/assets/images/Shop/not_available.jpg";
                    }}
                  />
                </div>

                {/* Subcategory Title */}
                <h6 className="beauty-subcat-title">
                  {item.subCategory}
                </h6>
              </div>
            </div>
          ))}
        </div>
      </div>

      <style>{`
        .beauty-sub-card-image {
          height: 180px;
        }
        .beauty-subcat-title {
          margin-top: 12px;
          text-align: center;
          font-size: 14px;
          font-weight: 700;
          color: #1A202C;
        }
        .beauty-sub-card-image:hover {
          transform: translateY(-5px);
          box-shadow: 0 10px 20px rgba(124, 58, 237, 0.12);
          border-color: #A847F0 !important;
        }
        @media (max-width: 767px) {
          .beauty-sub-card-image {
            height: 110px !important;
            border-radius: 12px !important;
          }
          .beauty-subcat-title {
            margin-top: 6px !important;
            font-size: 12.5px !important;
          }
        }
        @media (max-width: 420px) {
          .beauty-sub-card-image {
            height: 98px !important;
          }
          .beauty-subcat-title {
            font-size: 11.5px !important;
          }
        }
      `}</style>
    </section>
  );
};

export default BeautySubCategory;